PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT);
INSERT OR IGNORE INTO meta VALUES('schema_version','1');
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,title TEXT,created REAL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,session_id TEXT,role TEXT,content TEXT,created REAL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,session_id TEXT,state TEXT,spec TEXT,created REAL,updated REAL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,task_id TEXT,type TEXT,payload TEXT,created REAL);
CREATE TABLE IF NOT EXISTS calls(id TEXT PRIMARY KEY,task_id TEXT,tool TEXT,args TEXT,status TEXT,result TEXT,created REAL);
CREATE TABLE IF NOT EXISTS grants(id TEXT PRIMARY KEY,task_id TEXT,tool TEXT,call_id TEXT,scope TEXT,expires REAL,revoked INTEGER DEFAULT 0,source TEXT);
CREATE TABLE IF NOT EXISTS providers(id TEXT PRIMARY KEY,config TEXT);
CREATE TABLE IF NOT EXISTS usage(id TEXT PRIMARY KEY,task_id TEXT,provider TEXT,input_tokens INTEGER,output_tokens INTEGER,estimated INTEGER,cost REAL,created REAL);
CREATE TABLE IF NOT EXISTS memories(id TEXT PRIMARY KEY,scope TEXT,content TEXT,kind TEXT,source TEXT,created REAL,updated REAL);
CREATE VIRTUAL TABLE IF NOT EXISTS memory_fts USING fts5(id UNINDEXED,content);
CREATE TABLE IF NOT EXISTS schedules(id TEXT PRIMARY KEY,config TEXT,next_run REAL,enabled INTEGER);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT);
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY,name TEXT,mime TEXT,size INTEGER,created REAL);
CREATE TABLE IF NOT EXISTS changes(id TEXT PRIMARY KEY,task_id TEXT,path TEXT,before_text TEXT,after_sha TEXT,reverted INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS task_runtime(task_id TEXT PRIMARY KEY,revision INTEGER DEFAULT 0,verified_revision INTEGER,verification TEXT);
CREATE TABLE IF NOT EXISTS call_meta(call_id TEXT PRIMARY KEY,phase TEXT,workflow TEXT,step INTEGER,revision INTEGER,resource TEXT);
CREATE TABLE IF NOT EXISTS model_turns(id TEXT PRIMARY KEY,task_id TEXT,provider TEXT,message TEXT);
CREATE TABLE IF NOT EXISTS call_turns(call_id TEXT PRIMARY KEY,turn_id TEXT,provider_call_id TEXT);
CREATE TABLE IF NOT EXISTS steering(id INTEGER PRIMARY KEY AUTOINCREMENT,task_id TEXT,content TEXT,revision INTEGER,created REAL);
CREATE TABLE IF NOT EXISTS recovery(call_id TEXT PRIMARY KEY,decision TEXT,note TEXT,created REAL);
CREATE TABLE IF NOT EXISTS permission_rules(id TEXT PRIMARY KEY,task_id TEXT,workspace TEXT,tool TEXT,action TEXT,subject TEXT,scope TEXT,path TEXT,arguments TEXT,expires REAL,revoked INTEGER DEFAULT 0,source TEXT);
CREATE TABLE IF NOT EXISTS model_requests(id TEXT PRIMARY KEY,task_id TEXT,provider TEXT,status TEXT,attempt INTEGER,created REAL,detail TEXT);
UPDATE meta SET value='2' WHERE key='schema_version';
CREATE TABLE IF NOT EXISTS memory_history(id INTEGER PRIMARY KEY AUTOINCREMENT,memory_id TEXT,snapshot TEXT,created REAL);
